def criar_cliente_padrao_e_vincular_usuarios(apps, schema_editor):
    """Backfill dos usuários que já existiam antes do sistema virar
    multi-tenant: cria um Cliente "Padrão (Desenvolvimento)" e vincula a
    ele todo Profile que ainda não tenha um Cliente. Sem isso, os usuários
    já cadastrados ficariam sem Cliente e perderiam acesso às telas de
    negócio assim que o isolamento por tenant (Fase 5) entrar em vigor.

    Usa os models "históricos" (apps.get_model), como recomenda a
    documentação do Django para RunPython, em vez de importar
    apps.cliente.models.Cliente diretamente.
    """
    Cliente = apps.get_model("cliente", "Cliente")
    Profile = apps.get_model("accounts", "Profile")

    profiles_sem_cliente = Profile.objects.filter(cliente__isnull=True)
    if not profiles_sem_cliente.exists():
        return

    # CNPJ de exemplo com dígitos verificadores matematicamente válidos
    # (11.222.333/0001-81), amplamente usado como CNPJ de teste — apenas um
    # placeholder para não deixar o Cliente padrão com um documento que a
    # tela de edição rejeitaria caso alguém precise reabri-lo e salvar.
    cliente_padrao, _created = Cliente.objects.get_or_create(
        cpf_cnpj="11222333000181",
        defaults={
            "tipo_pessoa": "PJ",
            "nome_razao_social": "Cliente Padrão (Desenvolvimento)",
            "nome_fantasia": "Cliente Padrão",
            "ativo": True,
        },
    )
    profiles_sem_cliente.update(cliente=cliente_padrao)


def remover_vinculo_cliente_padrao(apps, schema_editor):
    """Reverso: apenas desfaz o vínculo (não apaga o Cliente nem os
    usuários), para a migração poder ser revertida com segurança."""
    Profile = apps.get_model("accounts", "Profile")
    Cliente = apps.get_model("cliente", "Cliente")
    Profile.objects.filter(cliente__cpf_cnpj="11222333000181").update(cliente=None)
    Cliente.objects.filter(cpf_cnpj="11222333000181").delete()


